def median(xs):
    s = sorted(xs)
    return s[len(s) // 2]

def is_prime(n):
    for i in range(2, int(n ** 0.5)):
        if n % i == 0:
            return False
    return True

def first_negative(xs):
    for i, x in enumerate(xs):
        if x <= 0:
            return i
    return -1

